<script setup lang="ts">import{ref,onMounted,computed}from 'vue';import{useRoute}from 'vue-router';import{runs,loadRun}from '../stores/runs';import{reviews,loadReviews}from '../stores/reviews';import{createReview}from '../api/reviews';import{exportRun,retryRun}from '../api/runs';import{isAdmin}from '../stores/auth';import{useTask}from '../hooks/useTask';import{usePolling}from '../hooks/usePolling';import{number}from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import StatusBadge from '../components/common/StatusBadge.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import CalibrationSummary from '../components/CalibrationSummary.vue';import MarginTable from '../components/MarginTable.vue';import ConvergenceChart from '../components/ConvergenceChart.vue';const route=useRoute();const note=ref('已检查边际残差、极端权重与有效样本，批准本次研究交付。');const{error,busy,execute}=useTask();const review=computed(()=>reviews.items.find(r=>r.run_id===Number(route.params.id)));const refresh=()=>execute(async()=>{await Promise.all([loadRun(Number(route.params.id)),loadReviews()])});onMounted(refresh);usePolling(()=>{if(['queued','running'].includes(runs.selected?.status||''))refresh()});const approve=(decision:string)=>execute(async()=>{await createReview({run_id:Number(route.params.id),decision,note:note.value});await loadReviews()});const download=()=>execute(()=>exportRun(Number(route.params.id)));
const retry=()=>execute(async()=>{await retryRun(Number(route.params.id));await loadRun(Number(route.params.id))});</script><template><PageHeading index="05" :title="runs.selected?.name||'读取校准记录'" subtitle="把边际匹配、权重离散与估计变化放在同一份底稿里。"/><ErrorNotice :message="error" @retry="refresh"/><template v-if="runs.selected"><div class="section-heading"><h2>{{runs.selected.batch?.name}}</h2><StatusBadge :status="runs.selected.status"/></div><p v-if="runs.selected.error" class="error">{{runs.selected.error}} <button v-if="runs.selected.status==='failed'&&runs.selected.has_snapshot" :disabled="busy" @click="retry">按原输入重试 ↻</button> <RouterLink to="/calibrations">调整输入后重新创建 →</RouterLink></p><p v-if="runs.selected.status==='failed'&&!runs.selected.has_snapshot" class="method-note">该历史任务缺少创建时的输入快照，不能重算；样本与目标以新建任务时的状态为准。</p><p v-if="['queued','running'].includes(runs.selected.status)" class="empty">后台正在逐维迭代；本页会自动刷新结果。</p><template v-if="runs.selected.status==='completed'&&runs.selected.result"><CalibrationSummary :result="runs.selected.result"/><p v-if="!runs.selected.result.converged" class="error">未收敛：权重不可批准。请检查目标兼容性、增加迭代次数或提高截断上限。</p><ConvergenceChart :trace="runs.selected.result.trace"/><div class="section-heading"><h2>边际核对</h2><span>同一目标总量 {{number(runs.selected.result.target_total,0)}}</span></div><MarginTable :items="runs.selected.result.diagnostics"/><p class="method-note">{{runs.selected.result.method_note}}</p><div class="weight-range"><span>权重范围 {{number(runs.selected.result.weight_min,4)}} — {{number(runs.selected.result.weight_max,4)}}</span><span>截断上限 {{number(runs.selected.result.weight_cap,4)}}</span></div><form v-if="isAdmin&&!review" @submit.prevent="approve('approved')" class="review-form"><h2>负责人复核</h2><label>复核说明<textarea v-model="note" rows="3" minlength="8" maxlength="500" required/></label><div class="form-actions"><button class="primary" :disabled="busy||!runs.selected.result.converged">批准权重口径 →</button><button type="button" :disabled="busy" @click="approve('rejected')">记录拒绝</button></div></form><div v-if="review" class="reviewed"><strong>{{review.decision==='approved'?'已批准交付':'未批准交付'}}</strong><p>{{review.note}}</p><button v-if="review.decision==='approved'" @click="download">下载完整权重 CSV ↓</button></div><p v-else-if="!isAdmin" class="method-note">等待抽样负责人复核后，方可导出完整权重。</p><p class="checksum">输入SHA256 / {{runs.selected.result.checksum}}</p></template></template></template>
